import unittest
from datetime import datetime
from fennel import next_run


class DowTest(unittest.TestCase):
    def test_sunday_is_zero(self):
        self.assertEqual(next_run('0 9 * * 0', datetime(2026, 3, 2, 10, 0)), datetime(2026, 3, 8, 9, 0))

    def test_timezone_aware(self):
        from zoneinfo import ZoneInfo
        after = datetime(2026, 3, 28, 1, 30, tzinfo=ZoneInfo('Europe/Paris'))
        self.assertEqual(next_run('30 2 * * *', after).utcoffset().total_seconds(), 7200)
